/**
 * Build a compact context summary for the Master Planner.
 *
 * The planner does not need the raw 180 sales rows -- that would blow the
 * context budget. We extract the headline numbers and the SKUs already
 * past or near reorder so the planner can pick the right subgoal first.
 *
 * Inputs reach this node via cross-node references to the four CSV-parse
 * nodes upstream. We do NOT mutate them, only summarize.
 *
 * Convergence guard: the four CSV-read branches fan out from "Set Goal" and
 * all converge on this node's single input. n8n runs this node once per
 * arriving branch rather than waiting for all four, so on the earlier
 * invocations the other branches have not executed yet and $('Read Sales JSON')
 * throws "hasn't been executed". We return [] on those invocations, which
 * emits no items and lets the run continue; the final invocation (after every
 * branch has landed) sees all four and emits the real summary exactly once.
 */
function ran(nodeName) {
  try {
    $(nodeName).all();
    return true;
  } catch (e) {
    return false;
  }
}

const REQUIRED = [
  'Read Inventory JSON',
  'Read Sales JSON',
  'Read Suppliers JSON',
  'Read Shipping JSON',
];
if (!REQUIRED.every(ran)) {
  return [];
}

const inventory = $('Read Inventory JSON').all().map(i => i.json);
const sales     = $('Read Sales JSON').all().map(i => i.json);
const suppliers = $('Read Suppliers JSON').all().map(i => i.json);
const goal      = $('Set Goal').first().json.goal;

const stockout_risk = inventory
  .filter(r => Number(r.on_hand) <= Number(r.reorder_point))
  .map(r => ({ sku: r.sku, name: r.name,
               on_hand: Number(r.on_hand),
               reorder_point: Number(r.reorder_point) }));

const overstock_risk = inventory
  .filter(r => Number(r.on_hand) > Number(r.reorder_point) * 5)
  .map(r => ({ sku: r.sku, name: r.name,
               on_hand: Number(r.on_hand),
               reorder_point: Number(r.reorder_point) }));

const supplier_summary = suppliers.map(s => ({
  supplier_id: s.supplier_id,
  on_time_rate: Number(s.on_time_rate),
  defect_rate: Number(s.defect_rate),
}));

return [{
  json: {
    goal,
    context_summary: {
      sku_count: inventory.length,
      sales_rows: sales.length,
      stockout_risk,
      overstock_risk,
      supplier_summary,
    },
  },
}];

/**
 * Extract the Master Planner's JSON from the Anthropic response envelope.
 * Anthropic returns { content: [{ type: "text", text: "..." }], ... }.
 *
 * If your planner replies with markdown fences (```json ...```), the
 * JSON.parse below will fail. Forbid fences in your system prompt
 * (preferred) or strip them here.
 */
const raw = $json.content[0].text.trim();
let plan;
try {
  plan = JSON.parse(raw);
} catch (e) {
  throw new Error("Planner did not return valid JSON. Got:\n" + raw.slice(0, 500));
}

// Validate next_subgoal against the routes that actually exist.
//
// This guard is the difference between a working agent and a safe one. The
// Switch downstream is configured with fallbackOutput "extra", which creates a
// fifth output for values it does not recognise — and nothing is connected to
// it. So if the planner ever emitted "audit_warehouse", or "Forecast" with a
// capital F, or "forecast " with a trailing space, the item would route into
// that dead output and the run would end with NO branch executed, NO error, and
// NO result. It would look like a success.
//
// A silent no-op is the worst failure mode an agent can have: nothing downstream
// can tell "the plan was empty" apart from "the plan ran". The LLM's output is
// untrusted input to a deterministic router, so it gets validated like any other
// untrusted input, at the boundary, and fails loudly.
const VALID_SUBGOALS = ["forecast", "inventory", "supplier", "logistics"];
if (!VALID_SUBGOALS.includes(plan.next_subgoal)) {
  throw new Error(
    "Planner emitted an unroutable next_subgoal: " +
      JSON.stringify(plan.next_subgoal) +
      ". Expected one of " + VALID_SUBGOALS.join(", ") +
      ". The Switch would have dropped this run silently."
  );
}

// Pull the goal+context through so downstream branches can reference them.
const ctx = $('Build Context Summary').first().json;

return [{ json: { ...plan, _goal: ctx.goal, _context: ctx.context_summary } }];

/**
 * Demand Forecasting Engine — classical statistical forecast.
 *
 * Pedagogical purpose
 * -------------------
 * This Code node implements the *classical* half of a hybrid planning
 * pipeline. It produces a deterministic, reproducible numeric forecast
 * for each SKU using:
 *   1. A 3-month moving average over recent demand
 *   2. A 12-month seasonal index that adjusts for cyclical patterns
 *
 * The downstream LLM node ("Forecast Context Adjuster") will take these
 * numbers and revise them using context the math cannot see — promotions,
 * news events, weather, viral product mentions. That handoff is the whole
 * point of the lesson: classical statistics for what is computable,
 * LLM reasoning for what is contextual.
 *
 * If your forecast looks suspicious (e.g. SKU-007 Wool Gloves projects
 * its low summer baseline forward), you have correctly built a *naive*
 * forecaster. The next node is supposed to catch what you missed.
 *
 * Reading: docs/planning-primer.md §"Classical vs LLM-based planning"
 */

// ---- Input contract -------------------------------------------------------
// This node sits on a Switch branch, so $input is the Master Planner's plan
// object, not the sales rows. We reach back to the CSV-parse node for the data,
// the same way the provided "Build Shipping Requests" node pulls its catalogue
// with $('Read Shipping JSON').
// Rows look like {month, sku, name, units_sold} (the parsed sales_history.csv).
const sales = $('Read Sales JSON').all().map(i => i.json);

// ---- Helpers (provided — do not change) -----------------------------------

function groupBySku(rows) {
  const out = {};
  for (const r of rows) {
    (out[r.sku] = out[r.sku] || []).push(r);
  }
  // Sort each SKU's series chronologically so "last 3" really means "most recent."
  for (const sku of Object.keys(out)) {
    out[sku].sort((a, b) => a.month.localeCompare(b.month));
  }
  return out;
}

function nextMonth(monthStr) {
  // "2025-12" -> "2026-01"
  const [y, m] = monthStr.split("-").map(Number);
  const d = new Date(Date.UTC(y, m, 1));
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

// ---- The two algorithms YOU implement -------------------------------------

/**
 * Compute a simple 3-month moving average over the most recent units_sold values.
 *
 * @param {Array<{units_sold: number}>} series  Full sorted series for one SKU.
 * @returns {number}  Mean of the last 3 months. If fewer than 3 months of
 *                    data exist, take the mean of what's available.
 *                    Empty series -> 0.
 *
 * Why this matters: the moving average is the simplest possible "trend"
 * estimator. It's a STRIPS-style assumption: we assume the recent past
 * predicts the near future. This breaks for viral products and discontinued
 * items — which is exactly why the seasonal index and the LLM step exist.
 */
function movingAverage(series) {
  if (!series || series.length === 0) return 0;

  // Take the most recent 3 months. slice(-3) yields the whole series when
  // fewer than 3 months exist, so short histories average what they have.
  const window = series.slice(-3);
  const total = window.reduce((acc, r) => acc + Number(r.units_sold), 0);

  return total / window.length;
}

/**
 * Seasonal index for a target forecast month.
 *
 * Definition for month M:
 *   index(M) = mean(units_sold across rows where month-of-year == M)
 *              / mean(units_sold across the entire series)
 *
 * Interpretation: 1.0 = "average month", 1.5 = "this month historically runs
 * 50% above average", 0.4 = "this month historically runs 60% below average."
 *
 * With only 12 months of history, the per-month mean degenerates to the
 * single observation we have for that month. That's a known weakness — we
 * accept it for this exercise. Production seasonality models use 2+ years.
 *
 * @param {Array<{month: string, units_sold: number}>} series
 * @param {string} targetMonth  e.g. "2026-01" — only the "01" portion matters.
 * @returns {number}            Multiplier. Default to 1.0 if you can't compute one.
 */
function seasonalIndex(series, targetMonth) {
  if (!series || series.length === 0) return 1.0;

  // "2026-01" -> "01". Only the month-of-year matters; the year is discarded
  // so that every January in the history contributes to January's index.
  const monthOfYear = targetMonth.split("-")[1];

  const sameMonth = series.filter(r => String(r.month).split("-")[1] === monthOfYear);

  // No observation for that calendar month: we have no seasonal evidence, so
  // stay neutral rather than inventing a multiplier.
  if (sameMonth.length === 0) return 1.0;

  const mean = rows =>
    rows.reduce((acc, r) => acc + Number(r.units_sold), 0) / rows.length;

  const monthMean = mean(sameMonth);
  const overallMean = mean(series);

  // A dead SKU (zero sales all year) has no meaningful ratio.
  if (overallMean === 0) return 1.0;

  return monthMean / overallMean;
}

// ---- Main loop (provided) -------------------------------------------------

const bySku = groupBySku(sales);
const results = [];

for (const sku of Object.keys(bySku)) {
  const series = bySku[sku];
  const last = series[series.length - 1].month;
  const target = nextMonth(last);

  // Classical forecast = trend (moving average) × seasonality
  const ma = movingAverage(series);
  const si = seasonalIndex(series, target);
  const forecast = ma * si;

  // Crude statistical confidence — coefficient of variation, inverted.
  // The downstream LLM is supposed to revise this when context demands it.
  // Watch how often statistical confidence and contextual confidence diverge.
  const variance = series.length > 1
    ? series.reduce((acc, r) => acc + Math.pow(r.units_sold - ma, 2), 0) / series.length
    : 0;
  const cv = ma > 0 ? Math.sqrt(variance) / ma : 1;
  const confidence = Math.max(0, Math.min(1, 1 - cv));

  // Contextual notes for the downstream LLM adjuster.
  //
  // The aggregates above are lossy on purpose: a moving average collapses the
  // SHAPE of the series into a single level. A SKU ramping 5x over three months
  // and a flat SKU can share a moving average, and the adjuster sees only the
  // aggregate — so on its own it cannot tell a viral product from a stable one.
  // We hand it a compact trend summary instead of all 12 rows, which would
  // multiply the token bill across every SKU on this branch.
  const units = series.map(r => Number(r.units_sold));
  const mean = a => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0);

  const notes = [`last_6_months=[${units.slice(-6).join(", ")}]`];

  // Two orthogonal views of the trend. We deliberately hand the LLM raw ratios
  // rather than a "cleaned" signal, for a reason worth stating:
  //
  // We cannot deseasonalize our way out of this. With 12 months of history each
  // calendar month appears exactly once, so seasonalIndex(m) degenerates to
  // units(m) / seriesMean — and dividing each month by that index returns the
  // series mean for every month. The ratio flattens to 1.0 for every SKU and
  // the signal is gone. Trend and seasonality are simply not identifiable from
  // one SKU's 12 points; separating them needs multiple years, or a peer group,
  // or knowledge of what the product IS.
  //
  // That last one is exactly what the LLM has and the arithmetic does not. It
  // knows a snow boot climbing into January is a season, and wool gloves at 6x
  // is not. So the honest division of labour: the code reports what moved, the
  // model judges whether that movement is ordinary for this product this month.
  const recent3 = mean(units.slice(-3));
  const prior9 = mean(units.slice(0, -3));
  const first3 = mean(units.slice(0, 3));

  // Spike: recent quarter against the rest of the year. High for a genuine ramp,
  // but ALSO high for any product entering its high season.
  if (prior9 > 0) {
    notes.push(`spike_ratio_recent3_vs_prior9=${Math.round((recent3 / prior9) * 100) / 100}`);
  }

  // Year trend: end of the year against the start. A cyclical product returns to
  // where it began (~1.0) because both ends sit in its off-season. A product in
  // true structural decline ends far below where it started. This is the ratio
  // that separates "December" from "dying".
  if (first3 > 0) {
    notes.push(`year_trend_last3_vs_first3=${Math.round((recent3 / first3) * 100) / 100}`);
  }

  results.push({
    sku,
    name: series[0].name,
    target_month: target,
    forecast_units: Math.round(forecast),
    moving_avg: Math.round(ma * 10) / 10,
    seasonal_index: Math.round(si * 100) / 100,
    statistical_confidence: Math.round(confidence * 100) / 100,
    method: "moving_avg_3 × seasonal_index",
    notes,
  });
}

// n8n Code-node return contract: array of {json: ...}
return results.map(r => ({ json: r }));

/**
 * Inventory Optimization Planner — Economic Order Quantity (EOQ).
 *
 * Pedagogical purpose
 * -------------------
 * EOQ (Wilson, 1934) is the canonical *classical* operations-research model:
 * a closed-form solution under strict assumptions —
 *   - constant demand
 *   - instantaneous replenishment
 *   - no stockouts allowed
 *   - fixed ordering cost, fixed holding cost
 *   - no quantity discounts
 *
 * Real e-commerce violates ALL of these for at least some SKUs. Viral
 * products (looking at you, SKU-007) blow past "constant demand." Discontinued
 * SKUs (SKU-013) make "no stockouts" expensive in the wrong direction.
 * Slow-movers make the formula numerically unstable.
 *
 * This node teaches the boundary problem: classical algorithms give crisp
 * answers exactly when their assumptions hold. Your two TODOs are
 *   (a) implement the formula
 *   (b) detect when its assumptions don't hold for a given SKU
 *
 * The downstream LLM exception node handles the SKUs you flag.
 *
 * Reading: docs/planning-primer.md §"STRIPS-style assumptions and where they break"
 */

// This node sits on a Switch branch, so $input carries the Master Planner's
// plan object rather than any data rows. We pull the two datasets directly from
// the CSV-parse nodes, mirroring the provided "Build Shipping Requests" node.
// The list is deliberately heterogeneous — inventory rows carry `on_hand`,
// sales rows carry `units_sold` — and partition() splits them apart below.
const all = [
  ...$('Read Inventory JSON').all().map(i => i.json),
  ...$('Read Sales JSON').all().map(i => i.json),
];

// Default ordering cost (S in the EOQ formula). In production this would
// vary by supplier and channel; we hard-code a single value so the focus
// stays on the formula and its assumptions.
const ORDERING_COST_USD = 50;

// ---- Helpers (provided) ---------------------------------------------------

function partition(rows) {
  const inventory = rows.filter(r => "on_hand" in r);
  const sales = rows.filter(r => "units_sold" in r);
  return { inventory, sales };
}

function annualDemand(salesForSku) {
  // Sum units_sold across the rows we have. With 12 months of data this is
  // the trailing-12-months annual demand.
  return salesForSku.reduce((acc, r) => acc + Number(r.units_sold), 0);
}

// ---- TODO #1 — the EOQ formula --------------------------------------------

/**
 * Wilson's Economic Order Quantity:
 *
 *   Q* = sqrt( (2 * D * S) / H )
 *
 * @param {number} D  Annual demand        (units per year)
 * @param {number} S  Fixed cost per order (dollars per order)
 * @param {number} H  Holding cost         (dollars per unit per year)
 * @returns {number}  Optimal order quantity, rounded to nearest integer.
 *
 * Hint: Math.sqrt is your friend. Guard against D=0 and H=0 — return 0 in
 *       either case. (You can't optimally order anything for zero demand,
 *       and dividing by zero holding cost is meaningless.)
 */
function eoq(D, S, H) {
  // No demand means there is no batch worth optimizing, and a zero holding cost
  // makes the ratio meaningless (the formula would divide by zero and imply an
  // infinite order). Both are outside the model's domain, so refuse rather than
  // return a number that looks authoritative.
  if (!D || D <= 0) return 0;
  if (!H || H <= 0) return 0;

  // Wilson (1934): the quantity where annual ordering cost and annual holding
  // cost are equal, which is where their sum is minimized.
  return Math.round(Math.sqrt((2 * D * S) / H));
}

// ---- TODO #2 — assumption-violation detection -----------------------------

/**
 * EOQ assumes:
 *   (a) demand is roughly constant
 *   (b) lead time is short enough to re-order before stocking out
 *   (c) the SKU isn't perishable (no holding-cost cliff)
 *   (d) demand volume is high enough that an "optimal batch" is meaningful
 *
 * Return an array of human-readable flag strings for any assumption that
 * FAILS for this SKU. An empty array means "EOQ is trustworthy here, ship
 * the formula's recommendation."
 *
 * Suggested checks (refine as you wish):
 *   - "viral_spike"   : mean(last 3 months) > 2.5 × mean(prior 9 months)
 *   - "declining"     : mean(last 3 months) < 0.5 × mean(first 3 months)
 *   - "low_velocity"  : annualDemand < 60   (less than ~5/month average)
 *   - "long_lead_time": inv.lead_time_days > 28 AND demand is volatile
 *
 * Note on perishability: none of our demo SKUs are perishable, so you do
 * NOT need a perishability check. Document the omission in your analysis
 * write-up — a real implementation would need it.
 *
 * @param {object} inv         Inventory row for the SKU
 * @param {Array}  salesSeries Chronologically sorted sales rows for the SKU
 * @returns {Array<string>}    Flag names, e.g. ["viral_spike", "low_velocity"]
 *
 * Hint: implement each check as its own small block. A flagged SKU may
 *       trigger multiple flags — that's expected and useful downstream.
 */
function detectViolations(inv, salesSeries) {
  const flags = [];
  if (!salesSeries || salesSeries.length === 0) return flags;

  const units = salesSeries.map(r => Number(r.units_sold));
  const mean = a => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0);

  const recent3 = mean(units.slice(-3));   // the quarter we are ordering for
  const prior9  = mean(units.slice(0, -3)); // the rest of the year
  const first3  = mean(units.slice(0, 3));  // where the year started
  const D = annualDemand(salesSeries);

  // (a) "demand is roughly constant" — broken upward.
  //
  // Threshold 2.5 is chosen against the data, not plucked from the air. Every
  // winter SKU (jackets, beanies, boots, blankets) ramps into Q4 at ~2.4x its
  // own annual baseline, and that is ordinary seasonality that EOQ's annual
  // demand figure already absorbs. Wool Gloves runs at ~6.2x. Setting the bar at
  // 2.5 puts it above routine seasonality and below the genuine viral event, so
  // the flag fires for the real anomaly and stays quiet for the other four.
  if (prior9 > 0 && recent3 > 2.5 * prior9) {
    flags.push("viral_spike");
  }

  // (b) "demand is roughly constant" — broken downward.
  //
  // Compared against the START of the year, not the rest of it. That choice is
  // what separates a dying product from a seasonal one. A summer SKU in December
  // has collapsed relative to its recent months, but it ends the year roughly
  // where it began (~1.3x) because January is also its off-season — it is not
  // dying, it is winter. A structurally declining SKU ends far below its own
  // January (Wired Earbuds: 0.41x). Comparing to prior9 instead would flag every
  // seasonal product in the catalogue.
  if (first3 > 0 && recent3 < 0.5 * first3) {
    flags.push("declining");
  }

  // (c) "an optimal batch is meaningful" — broken by thin volume.
  //
  // Under ~5 units/month the sqrt is dominated by noise: one lumpy month moves
  // Q* enough to make the "optimum" arbitrary. Better to admit the model has
  // nothing useful to say than to ship a precise-looking number.
  if (D < 60) {
    flags.push("low_velocity");
  }

  // (d) "replenishment is instantaneous" — broken by a long, risky lead time.
  //
  // EOQ has no lead-time term at all: it assumes stock appears when ordered. A
  // long lead time only actually hurts when demand is also volatile, because a
  // steady seller can be covered by a reorder point. Volatility is measured with
  // the coefficient of variation so it is scale-free and comparable across SKUs
  // selling 5 or 500 units.
  const avg = mean(units);
  const sd = avg > 0
    ? Math.sqrt(mean(units.map(u => Math.pow(u - avg, 2))))
    : 0;
  const cv = avg > 0 ? sd / avg : 0;
  if (Number(inv.lead_time_days) > 28 && cv > 0.5) {
    flags.push("long_lead_time");
  }

  // (e) Dead stock: a glut that demand will never come back to clear.
  //
  // Note what this check is NOT. A naive "on_hand > 5x reorder_point" flag looks
  // reasonable and is badly wrong on this catalogue: it fires on Sunglasses,
  // Beach Towel and Swim Trunks, which are simply summer SKUs holding stock
  // through their off-season. By months-of-cover they are indistinguishable from
  // the genuinely dead SKU — Sunglasses carries 6.9 months, Wired Earbuds 6.8.
  //
  // The pile size is not the signal. What matters is whether demand is coming
  // back for it. A seasonal glut clears itself next season; a glut on a decaying
  // product never clears and only accrues holding cost. So overstock is only a
  // violation IN CONJUNCTION with decline, and that conjunction is the thing
  // worth routing to a human-style judgement.
  const onHand = Number(inv.on_hand);
  const rop = Number(inv.reorder_point);
  const overstocked = rop > 0 && onHand > 5 * rop;
  if (overstocked && flags.includes("declining")) {
    flags.push("dead_stock");
  }

  // Deliberately NOT implemented: perishability. EOQ's holding cost is linear in
  // time, which is wrong for anything with a shelf life (spoilage is a cliff, not
  // a slope). None of the 15 demo SKUs are perishable and the dataset carries no
  // expiry field, so a check here could never fire. Noted in analysis.md.

  return flags;
}

// ---- Main loop (provided) -------------------------------------------------

const { inventory, sales } = partition(all);
const salesBySku = sales.reduce((acc, r) => {
  (acc[r.sku] = acc[r.sku] || []).push(r);
  return acc;
}, {});
for (const sku of Object.keys(salesBySku)) {
  salesBySku[sku].sort((a, b) => a.month.localeCompare(b.month));
}

const results = [];
for (const inv of inventory) {
  const series = salesBySku[inv.sku] || [];
  const D = annualDemand(series);
  const H = Number(inv.holding_cost_per_unit_year);
  const Q = eoq(D, ORDERING_COST_USD, H);
  const flags = detectViolations(inv, series);

  results.push({
    sku: inv.sku,
    name: inv.name,
    on_hand: Number(inv.on_hand),
    reorder_point: Number(inv.reorder_point),
    annual_demand: D,
    eoq_units: Q,
    holding_cost_per_unit_year: H,
    ordering_cost_usd: ORDERING_COST_USD,
    assumption_flags: flags,
    needs_llm_review: flags.length > 0,
  });
}

return results.map(r => ({ json: r }));

/**
 * Manufacture three illustrative shipping requests so the logistics branch
 * has work to do. In a real system these would come from order management;
 * we synthesize them here so the assignment is self-contained.
 */
const requests = [
  { type: "request", request_id: "REQ-001", weight_kg:  850, origin_region: "Asia",          dest_region: "North America", deadline_days: 14, perishable: false },
  { type: "request", request_id: "REQ-002", weight_kg:   60, origin_region: "North America", dest_region: "North America", deadline_days:  3, perishable: true  },
  { type: "request", request_id: "REQ-003", weight_kg: 1200, origin_region: "Europe",        dest_region: "North America", deadline_days: 21, perishable: false },
];
// Emit the REQUESTS only.
//
// Originally this node also appended the 10 carrier options, so the branch's
// next node received 13 items. The Logistics Coordinator is a per-item LLM node,
// so that meant 13 API calls per run, ten of which handed a carrier option to a
// prompt that expects a shipping request. Both consumers pull the catalogue for
// themselves instead — the LLM node via $('Read Shipping JSON') in its body
// expression, the classical fallback via the same reference in its code — so the
// options do not need to travel through the item stream at all. 3 requests in,
// 3 LLM calls out.
return requests.map(x => ({ json: x }));

/**
 * Classical Logistics Planner — greedy fallback.
 *
 * Pedagogical purpose
 * -------------------
 * This is the "planning without an LLM" branch of the Logistics Coordinator.
 * The LLM logistics node handles soft-constraint cases (special instructions,
 * supplier relationships, urgency framing, multi-leg trade-offs). When the
 * upstream IF node decides a situation is purely numerical — fixed weight,
 * fixed deadline, available carriers — it routes here for a deterministic,
 * auditable choice.
 *
 * Greedy is the simplest classical search: at each decision point, take the
 * locally best option. It's not always globally optimal, but it's fast,
 * explainable, and a perfect baseline to compare LLM plans against.
 *
 * Reading: docs/planning-primer.md §"Classical search and the cost of optimality"
 */

// Inputs are merged upstream — shipping requests AND the catalogue of options.
//
// A request: { type: "request", request_id, weight_kg, origin_region,
//              dest_region, deadline_days, perishable }
// An option: { type: "option",  option_id, carrier, mode, origin_region,
//              destination_region, transit_days, cost_per_kg,
//              max_weight_kg, supports_perishable }

// $input here is whatever the IF node passed through — the Logistics LLM's raw
// response envelopes, not the requests themselves. The IF forwards exactly those
// requests the LLM flagged as purely numeric, so the envelopes tell us WHICH
// requests were handed to us; we then fetch the real data from the nodes that
// own it.
const routedIds = new Set(
  $input.all()
    .map(i => {
      try {
        const text = i.json.content[0].text.replace(/```(?:json)?/g, "").trim();
        return JSON.parse(text).request_id;
      } catch (e) {
        return null;
      }
    })
    .filter(Boolean)
);

const allRequests = $('Build Shipping Requests').all().map(i => i.json);

// Re-plan only what was routed here. Falling back to the full set keeps the node
// runnable standalone (Execute Node) when there is no upstream IF output to read.
const requests = routedIds.size
  ? allRequests.filter(r => routedIds.has(r.request_id))
  : allRequests;

const options = $('Read Shipping JSON').all().map(i => i.json);

// ---- TODO — greedy carrier assignment -------------------------------------

/**
 * Pick the cheapest shipping option satisfying ALL hard constraints
 * for one request:
 *   - origin_region matches request.origin_region
 *   - destination_region matches request.dest_region
 *   - transit_days <= request.deadline_days
 *   - max_weight_kg >= request.weight_kg
 *   - if request.perishable === true, supports_perishable must also be true
 *
 * Total cost = request.weight_kg × option.cost_per_kg  (we ignore time cost)
 *
 * @param {object} req
 * @param {Array}  options
 * @returns {object|null}  Chosen option augmented with `total_cost_usd`,
 *                         or null if nothing satisfies the constraints.
 *
 * Hint: this is two steps — filter, then min-by-cost.
 *   1. Array.prototype.filter against the 5 hard constraints.
 *   2. If the filtered list is empty, return null (infeasible).
 *   3. Map each survivor to {...option, total_cost_usd: req.weight_kg * option.cost_per_kg}.
 *   4. Reduce to the one with the minimum total_cost_usd.
 *
 * Why greedy and not exhaustive? With ~10 options per request the search
 * space is trivial. We use greedy to keep the comparison clean against
 * the LLM branch, not because we couldn't afford the optimal search.
 */
function pickCheapestFeasible(req, options) {
  // Step 1 — feasibility. These are HARD constraints: an option either satisfies
  // all of them or it is not a candidate at all. There is no trading a day of
  // lateness against a cheaper rate here; that kind of judgement is exactly what
  // the LLM branch is for. This branch is the deterministic, auditable one.
  const feasible = options.filter(opt => {
    if (opt.origin_region !== req.origin_region) return false;
    if (opt.destination_region !== req.dest_region) return false;
    if (Number(opt.transit_days) > Number(req.deadline_days)) return false;
    if (Number(opt.max_weight_kg) < Number(req.weight_kg)) return false;

    // Perishable cargo may only ride a carrier that supports it. The CSV parses
    // this column as the strings "true"/"false", so compare loosely rather than
    // trusting a boolean to have survived the trip.
    if (req.perishable === true) {
      const supports =
        opt.supports_perishable === true || opt.supports_perishable === "true";
      if (!supports) return false;
    }
    return true;
  });

  // Step 2 — infeasible is a real answer, not an error. REQ-002 (60kg, perishable,
  // 3-day deadline) has no carrier: the only perishable-capable North America
  // lane is UPS Ground at 5 days. Returning null lets the caller report "no
  // feasible carrier" instead of inventing one that breaks a hard constraint.
  if (feasible.length === 0) return null;

  // Step 3 — greedy: among the survivors, take the cheapest. Cost is linear in
  // weight, so the per-kg rate decides it. With ~10 options the exhaustive search
  // IS this search; greedy is not an approximation here, it is optimal. We use it
  // because it is a clean, explainable baseline to hold the LLM's plan against.
  return feasible
    .map(opt => ({
      ...opt,
      total_cost_usd:
        Math.round(Number(req.weight_kg) * Number(opt.cost_per_kg) * 100) / 100,
    }))
    .reduce((best, opt) => (opt.total_cost_usd < best.total_cost_usd ? opt : best));
}

// ---- Main loop (provided) -------------------------------------------------

const assignments = [];
for (const req of requests) {
  const choice = pickCheapestFeasible(req, options);
  assignments.push({
    request_id: req.request_id,
    weight_kg: req.weight_kg,
    deadline_days: req.deadline_days,
    chosen: choice,
    feasible: choice !== null,
    method: "classical_greedy",
  });
}

return assignments.map(a => ({ json: a }));

/**
 * Aggregate the active subgoal's output into a final business-friendly summary.
 * Only one branch fires per execution (the Switch routes on next_subgoal).
 *
 * Three jobs:
 *   1. Turn the branch's raw LLM envelopes into findings a human would read.
 *   2. Close the HTN loop by naming the next subgoal in the plan, so a
 *      subsequent run can advance the plan instead of restarting it.
 *   3. Tally tokens and cost, because a planner you cannot budget is a planner
 *      you cannot run.
 */

// ---- Robust extraction ----------------------------------------------------
//
// Every LLM node is told to emit exactly one raw JSON object. Sometimes one
// does not: models wrap output in ```json fences, or narrate ("Wait, let me
// re-examine...") and emit a corrected second object. A pipeline that dies on
// one malformed reply out of fifteen is not worth much, so we recover instead
// of throwing. When several objects are present the LAST one wins, which is
// precisely the model's own correction.
function extractJson(text) {
  if (typeof text !== "string") return null;

  const cleaned = text.replace(/```(?:json)?/gi, "").trim();

  // The common case: the whole reply is one valid JSON value. This also covers
  // the supplier node, which returns an ARRAY of six scored suppliers rather
  // than a single object (their scores are relative, so they are produced in one
  // call). The brace-scanner below would only recover the last element of it.
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // Fall through to salvage.
  }

  // Salvage. Models narrate: the supplier node has shown its min-max arithmetic
  // in markdown tables before emitting the array, and the per-SKU nodes have
  // occasionally emitted a second object to correct a first. Scan for balanced
  // JSON regions starting at either bracket and keep everything that parses.
  const found = [];
  const OPEN = { "{": "}", "[": "]" };
  for (let i = 0; i < cleaned.length; i++) {
    const close = OPEN[cleaned[i]];
    if (!close) continue;

    let depth = 0;
    for (let j = i; j < cleaned.length; j++) {
      if (cleaned[j] === cleaned[i]) depth++;
      else if (cleaned[j] === close) depth--;

      if (depth === 0) {
        try {
          found.push(JSON.parse(cleaned.slice(i, j + 1)));
          i = j; // consume the region so we do not rescan its interior
        } catch (e) {
          // Not valid; leave i alone and let the outer loop advance.
        }
        break;
      }
    }
  }

  if (!found.length) return null;

  // An array is the richest result (the full supplier roster) — prefer the
  // longest one. Otherwise take the LAST object, which is the model's own
  // correction when it revised itself mid-reply.
  const arrays = found.filter(Array.isArray);
  if (arrays.length) {
    return arrays.reduce((a, b) => (b.length > a.length ? b : a));
  }
  return found[found.length - 1];
}

// An item is either an Anthropic response envelope (the LLM branches) or a
// plain object (the classical logistics fallback, which is pure JS).
function unwrap(item) {
  const text = item && item.content && item.content[0] && item.content[0].text;
  if (typeof text === "string") {
    const parsed = extractJson(text);
    return parsed !== null ? parsed : { unparsed: text.slice(0, 200) };
  }
  return item;
}

// ---- Plan context ---------------------------------------------------------

const plan = $('Parse Plan').first().json;
const executed = plan.next_subgoal;

// A node may hand back one object per item (the per-SKU branches) or a single
// item holding an array (the supplier roster). Flatten so downstream code sees
// one flat list of results either way.
const results = $input.all().flatMap(i => {
  const u = unwrap(i.json);
  return Array.isArray(u) ? u : [u];
});

// ---- Findings, per branch -------------------------------------------------

const findings = [];
const money = n => Math.round(Number(n) * 100) / 100;

if (executed === "forecast") {
  const revised = results.filter(r => Number(r.delta_pct));
  const classical = {};
  for (const r of $('Demand Forecast Engine').all()) classical[r.json.sku] = r.json;

  for (const r of revised) {
    const c = classical[r.sku] || {};
    const dir = Number(r.delta_pct) > 0 ? "raised" : "cut";
    findings.push(
      `${r.sku} ${c.name || ""}: forecast ${dir} ${c.forecast_units} -> ` +
      `${r.revised_forecast} units (${r.delta_pct > 0 ? "+" : ""}${r.delta_pct}%). ${r.reasoning || ""}`
    );
  }
  findings.push(
    `${results.length - revised.length} of ${results.length} SKUs held at the classical forecast.`
  );
} else if (executed === "inventory") {
  const act = results.filter(r => r.recommended_action && r.recommended_action !== "hold");
  for (const r of act) {
    findings.push(
      `${r.sku}: ${String(r.recommended_action).toUpperCase()} ` +
      `qty ${r.recommended_qty}. ${r.reasoning || ""}`
    );
  }
  findings.push(
    `${results.length - act.length} of ${results.length} SKUs need no action ` +
    `(on hand above reorder point, EOQ assumptions intact).`
  );
} else if (executed === "supplier") {
  const ranked = results
    .filter(r => r.supplier_id)
    .sort((a, b) => Number(b.score_total) - Number(a.score_total));
  for (const r of ranked) {
    findings.push(
      `${r.supplier_id}: ${r.score_total}/100 (${r.tier}). ${r.recommendation || ""}`
    );
  }
} else if (executed === "logistics") {
  for (const r of results) {
    if (r.chosen) {
      // Classical greedy fallback shape.
      findings.push(
        `${r.request_id}: ${r.chosen.carrier} ${r.chosen.mode} ` +
        `$${money(r.chosen.total_cost_usd)} (${r.method}).`
      );
    } else if (r.feasible === false) {
      findings.push(`${r.request_id}: NO FEASIBLE CARRIER under the stated constraints.`);
    } else if (r.request_id) {
      // LLM shape.
      findings.push(
        `${r.request_id}: ${r.chosen_option_id}. ${r.trade_off_summary || ""}`
      );
    }
  }
}

// ---- Close the HTN loop ---------------------------------------------------
//
// The planner emitted an ORDERED list of subgoals. We executed one of them; the
// next unexecuted one in that order is what a follow-up run should dispatch.
// This is the hook that turns a single-shot pipeline into an iterative planner.
const ordered = (plan.subgoals || []).map(s => s.type);
const at = ordered.indexOf(executed);
const next_recommended_subgoal =
  at !== -1 && at + 1 < ordered.length ? ordered[at + 1] : null;

// ---- Cost accounting ------------------------------------------------------
//
// Claude Sonnet 4.6: $3 per Mtok in, $15 per Mtok out.
const LLM_NODES = [
  'Master Planner Agent',
  'Forecast Context Adjuster',
  'Inventory Exception Handler',
  'Supplier Performance Monitor',
  'Logistics Coordinator (LLM)',
];

let tokens_in = 0;
let tokens_out = 0;
let llm_calls = 0;
for (const name of LLM_NODES) {
  let items;
  try {
    items = $(name).all();
  } catch (e) {
    continue; // node not on this run's branch
  }
  for (const it of items) {
    const u = it.json && it.json.usage;
    if (!u) continue;
    llm_calls++;
    tokens_in += Number(u.input_tokens || 0);
    tokens_out += Number(u.output_tokens || 0);
  }
}
const cost_usd = money((tokens_in * 3) / 1e6 + (tokens_out * 15) / 1e6);

return [{
  json: {
    plan_id: plan.plan_id,
    goal: plan._goal,
    executed_subgoal: executed,
    planned_subgoals: ordered,
    key_findings: findings,
    next_recommended_subgoal,
    run_metrics: {
      llm_calls,
      tokens_in,
      tokens_out,
      cost_usd: Number(((tokens_in * 3) / 1e6 + (tokens_out * 15) / 1e6).toFixed(4)),
    },
  },
}];
